 jobs=[('Ejer / teknisk direktør / elautoriseret maskinmester','ELOHVAC ApS · København · maj 2023–nu','8 medarbejdere inkl. 3 lærlinge · fuldt P&L',[('Ledelse og projekter','Leder fem elektrikere og tre lærlinge med planlægning, 1:1 og oplæring; arbejder med kunder, leverandører og underentreprenører.'),('Metoder og opfølgning','Egne værktøjer til tilbud, tidsplaner og kvalitetstjek gav over 40 % dokumenteret produktivitetsløft.')]),('Senior commissioning engineer / projektleder, elsystemer','Novo Nordisk A/S · nov. 2022–jul. 2024','37 samtidige CAPEX-projekter · 25 specialister',[('Koordinering og kvalitet','Koordinerede engineering, indkøb og anlæg, fremdrift, økonomi og risiko. FAT/SAT og IQ/OQ/PQ med nul kritiske afvigelser ved aflevering.')]),('Projekt- og værkstedsleder','Ventek-Air · jan. 2022–nov. 2022','14 medarbejdere · 11 samtidige projekter',[('Kapacitet og entreprenører','Ledede daglig planlægning og koordinerede underentreprenører; tavlemøder og flaskehalsanalyse.')]),('Drifts- og vedligeholdelsesleder / værkstedstekniker','BIOFOS, Lynetten · aug. 2017–jan. 2022','Kritisk 24/7-drift',[('Teknisk drift','Forebyggende vedligehold, el- og mekanisk fejlfinding, højspændingsanlæg og SCADA.')]),('Elektromekaniker / produktionsteamleder','ARJ Engineering · dec. 2003–mar. 2010','12 mekanikere og teknikere',[('Mennesker og teknik','Vagtplanlægning og materialekoordinering; diagnose og reparation af industrielt udstyr.')]),('Medejer og CTO / teknisk ansvarlig, AI-afdeling','Data Power Consultant ApS · København · 2024–nov. 2026 · sideløbende med ELOHVAC','4–10 personer · virksomheden ophørt',[('Systemer og dokumentation','Ledede tekniske applikationer fra behov og integration til dokumentation og overdragelse.')])]
