 rows=[('10/0,4 kV distributionsnet og komponenter','Direkte arbejde med distributionsnettet er bekræftet; specifikke komponenter, projekter og arbejdsgivere er ikke oplyst. Maskinmester med LV/MV/HV-autorisation.'),('Projektledelse og entreprisestyring','Mindst tre års erfaring med begge dele i el- eller beslægtede brancher er bekræftet; perioder og konkrete projekter ikke specificeret. Ventek-Air: underentreprenører.'),('Personaleledelse og kompetencer','ELOHVAC: otte medarbejdere med daglig ledelse, 1:1 og oplæring; Ventek-Air: 14 medarbejdere. Vil udvikle kompetencer og afklare kapacitet i teamet.'),('Ledelse af 16–18 specialister','Novo: koordinerede 25 specialister; Ventek-Air: 14 medarbejdere. Vil støtte de forskellige faggrupper med nærvær, mål og faglig sparring.'),('Kundeaftaler og kundens forventninger','ELOHVAC: kundekontakt og tekniske opgaver. Vil afstemme leverancer, ansvar og tilbagemeldinger med team, kunde og entreprenør.'),('Planlægning, projektering og udførelse','Novo: planlagde og koordinerede engineering, indkøb og anlæg på 37 projekter. Vil aftale beslutningspunkter og grænseflader med Nexels fagpersoner.'),('Dokumentation og myndighedsrapportering','Novo: FAT/SAT og IQ/OQ/PQ med nul kritiske afvigelser ved aflevering. Vil afklare dokumentkrav, ejerskab og rapportering efter Nexels gældende procedurer.'),('Økonomisk styring og effektive processer','ELOHVAC: fuldt P&L og egne værktøjer med over 40 % produktivitetsløft. Vil skabe synlig økonomiopfølgning og følge afvigelser i kundeprojekter.'),('Fælles retning og mål i ledergruppen','Ventek-Air: daglig planlægning af 11 samtidige projekter. Vil omsætte afdelingens mål til teammål og afstemme prioriteringer med de øvrige ledere.'),('Ensartede metoder på tværs af fire teams','Lean og Six Sigma anvendt i praksis; PRINCE2 certificeret. Vil udvikle og afprøve fælles arbejdsgange med medarbejdere og ledere før udrulning.'),('Tværorganisatoriske fora og entreprenører','Novo: koordinering på tværs af engineering, indkøb og anlæg; Ventek-Air: underentreprenører. Vil fokusere på beslutninger, grænseflader og opfølgning.'),('Teknisk baggrund og sikkerhed','Elautoriseret maskinmester og B.Tech med el-/mekanikbaggrund. Vil følge Nexels sikkerhedsprocedurer og sikre, at opgaver udføres af rette fagpersoner.')]
 m.models_table('ROLLEBEHOV — ERFARING OG TILGANG',('Krav i rollen','Erfaring eller foreslået tilgang'),rows,widths=(2600,7746))
